// The app's face on the home screen, named "NoteLetter". Until 2026-11-03 this
// app shipped Flutter's stock blue icon on iOS and Android and was called
// "NoteLetter Flutter". Nothing failed: an icon and a name are assets no Dart
// code reads.
//
// The icon is generated by tool/app_icons.mjs from the drawings every client
// renders (../NoteLetter-contracts/assets/app-icon/). This test holds the
// drawings to the mark and AppColors, and the committed files to the drawings,
// so a re-run of `flutter create`, a hand-dropped PNG or a palette move goes red.
import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';
import 'dart:ui' as ui;

import 'package:flutter/material.dart';
import 'package:flutter_app/theme/app_colors.dart';
import 'package:flutter_test/flutter_test.dart';

String _hex(Color c) =>
    '#${(c.toARGB32() & 0xFFFFFF).toRadixString(16).padLeft(6, '0').toUpperCase()}';

String _art(String name) =>
    File('../NoteLetter-contracts/assets/app-icon/$name').readAsStringSync();

String _markPath() {
  final svg = File('../NoteLetter-browserextension/assets/logo-mark.svg')
      .readAsStringSync();
  final m = RegExp(r'<path[^>]*\sd="([^"]+)"').firstMatch(svg);
  expect(m, isNotNull, reason: 'logo-mark.svg has no path');
  return m!.group(1)!;
}

/// A drawing's quill layers, in paint order.
List<RegExpMatch> _quills(String name) => RegExp(
        r'<path transform="translate\(([-\d.]+) ([-\d.]+)\) scale\(([\d.]+)\)" fill="(#[0-9A-Fa-f]{6})" d="([^"]+)"')
    .allMatches(_art(name))
    .toList();

/// A vector drawable's layers as they would be read off the same drawing.
List<List<String?>> _vectorLayers(String xml) => RegExp(
        r'android:translateX="([^"]+)"\s+android:translateY="([^"]+)"\s+android:scaleX="([^"]+)"\s+android:scaleY="([^"]+)">\s+<path\s+android:fillColor="([^"]+)"\s+android:pathData="([^"]+)"')
    .allMatches(xml)
    .map((m) => [m[1], m[2], m[3], m[5], m[6]])
    .toList();

Future<ByteData> _rgba(String path, {required int size}) async {
  final codec = await ui.instantiateImageCodec(File(path).readAsBytesSync());
  final image = (await codec.getNextFrame()).image;
  expect(image.width, size, reason: '$path is ${image.width}px');
  return (await image.toByteData(format: ui.ImageByteFormat.rawRgba))!;
}

int _px(ByteData d, int size, int x, int y) {
  final i = (y * size + x) * 4;
  return (d.getUint8(i) << 16) | (d.getUint8(i + 1) << 8) | d.getUint8(i + 2);
}

int _rgb(Color c) => c.toARGB32() & 0xFFFFFF;

void main() {
  test('every drawing is the extension\'s mark, in AppColors', () {
    for (final name in const [
      'noteletter-icon-1024.svg',
      'noteletter-icon-flat.svg',
      'noteletter-icon-mono.svg',
      'favicon.svg',
      'android/ic_launcher_foreground.svg',
      'android/ic_launcher_monochrome.svg',
    ]) {
      final quills = _quills(name);
      expect(quills, isNotEmpty, reason: name);
      for (final q in quills) {
        expect(q[5], _markPath(), reason: '$name: the quill is one path everywhere');
      }
    }
    for (final name in const [
      'noteletter-icon-1024.svg',
      'noteletter-icon-flat.svg',
    ]) {
      expect(_art(name), contains('<rect width="1024" height="1024" fill="${_hex(AppColors.primary)}"/>'),
          reason: '$name: the cloth is --brick-500');
      final fills = _quills(name).map((q) => q[4]).toList();
      expect(fills.length, 3, reason: '$name: light edge, dark edge, quill');
      expect(fills[1], _hex(AppColors.sealLight), reason: 'the dark edge is --brick-700');
      expect(fills[2], _hex(AppColors.primaryForeground), reason: 'the quill is --paper-50');
    }
  });

  test('the Android adaptive icon is the drawing, layer for layer', () {
    const res = 'android/app/src/main/res';
    final bg = File('$res/values/ic_launcher_background.xml').readAsStringSync();
    expect(bg, contains('>${_hex(AppColors.primary)}</color>'),
        reason: 'the background is the cloth, --brick-500');

    void holds(String file, String drawing, int layers) {
      final got = _vectorLayers(File('$res/drawable/$file').readAsStringSync());
      final want = _quills(drawing)
          .map((q) => [q[1], q[2], q[3], q[4], q[5]])
          .toList();
      expect(want.length, layers, reason: drawing);
      expect(got, want, reason: '$file: re-run tool/app_icons.mjs');
    }

    holds('ic_launcher_foreground.xml', 'android/ic_launcher_foreground.svg', 3);
    holds('ic_launcher_monochrome.xml', 'android/ic_launcher_monochrome.svg', 1);

    final adaptive = File('$res/mipmap-anydpi-v26/ic_launcher.xml').readAsStringSync();
    expect(adaptive, contains('<background android:drawable="@color/ic_launcher_background"/>'));
    expect(adaptive, contains('<foreground android:drawable="@drawable/ic_launcher_foreground"/>'));
    expect(adaptive, contains('<monochrome android:drawable="@drawable/ic_launcher_monochrome"/>'));
    final manifest =
        File('android/app/src/main/AndroidManifest.xml').readAsStringSync();
    expect(manifest, contains('android:icon="@mipmap/ic_launcher"'));
  });

  test('iOS is handed layers with every effect off, and Xcode builds them', () {
    // Given a bitmap, iOS 26 segments the icon and applies Liquid Glass: the
    // weave and the pressed edge vanish and the quill turns a translucent pink.
    // No test can see that; it took the 26.5 home screen. What can be held is
    // that the system is told to draw the art, and that the target carries it.
    // Xcode flattens every iOS below 26's bitmaps from this same file.
    final icon = jsonDecode(File('ios/Runner/AppIcon.icon/icon.json').readAsStringSync())
        as Map<String, dynamic>;
    final groups = (icon['groups'] as List).cast<Map<String, dynamic>>();
    Map<String, dynamic> only(Map<String, dynamic> g) =>
        (g['layers'] as List).single as Map<String, dynamic>;
    expect(groups.map((g) => only(g)['name']), ['quill', 'cloth'],
        reason: 'the first group is the frontmost');
    for (final g in groups) {
      expect(g['specular'], isFalse);
      expect((g['shadow'] as Map)['kind'], 'none');
      expect((g['translucency'] as Map)['enabled'], isFalse);
      expect(only(g)['glass'], isFalse, reason: '${only(g)['name']} would turn to glass');
    }

    // Tinted is the handoff's: the mono quill on nothing, cloth and fill gone.
    expect(only(groups[0])['image-name-specializations'], [
      {'value': 'quill.png'},
      {'appearance': 'tinted', 'value': 'quill-mono.png'},
    ]);
    expect(only(groups[1])['image-name'], 'cloth.png');
    expect(only(groups[1])['hidden-specializations'], [
      {'appearance': 'tinted', 'value': true},
    ]);
    final fills = (icon['fill-specializations'] as List).cast<Map<String, dynamic>>();
    expect(fills[1], {'appearance': 'tinted', 'value': 'none'});
    final solid = ((fills[0]['value'] as Map)['solid'] as String)
        .replaceFirst('srgb:', '')
        .split(',')
        .map(double.parse)
        .toList();
    expect((solid[0] * 255).round() << 16 | (solid[1] * 255).round() << 8 | (solid[2] * 255).round(),
        _rgb(AppColors.primary),
        reason: 'the fill is the cloth, --brick-500');

    final project = File('ios/Runner.xcodeproj/project.pbxproj').readAsStringSync();
    expect(project, contains('path = AppIcon.icon;'));
    final build = RegExp(r'(\w{24}) /\* AppIcon\.icon in Resources \*/ = \{isa = PBXBuildFile')
        .firstMatch(project)?.group(1);
    expect(build, isNotNull, reason: 'a re-created project drops the layered icon');
    final phases = RegExp(r'isa = PBXResourcesBuildPhase;[\s\S]*?\);').allMatches(project);
    final runner = phases.where((m) => m[0]!.contains('Assets.xcassets in Resources'));
    expect(runner.single[0], contains('$build /* AppIcon.icon in Resources */'),
        reason: 'the Runner target must build it beside the catalog');
  });

  testWidgets('the icon PNGs are those drawings, not Flutter\'s stock icon',
      (tester) async {
    await tester.runAsync(() async {
      final weave = RegExp(r'stroke="(#[0-9A-Fa-f]{6})"')
          .firstMatch(_art('noteletter-icon-1024.svg'))![1]!;

      // The catalog a toolchain below Xcode 26 builds: one 1024 in the Any and
      // Dark slots, full-bleed with NO alpha channel (iOS masks it, and the App
      // Store refuses alpha). PNG colour type 2 is RGB with no alpha.
      const set = 'ios/Runner/Assets.xcassets/AppIcon.appiconset';
      final contents = jsonDecode(File('$set/Contents.json').readAsStringSync())
          as Map<String, dynamic>;
      String appearance(Map<String, dynamic> image) {
        final list = image['appearances'] as List?;
        return list == null ? 'any' : (list.first as Map)['value'] as String;
      }

      final slots = {
        for (final i in (contents['images'] as List).cast<Map<String, dynamic>>())
          appearance(i): i['filename'],
      };
      expect(slots, {
        'any': 'AppIcon-1024.png',
        'dark': 'AppIcon-1024.png',
        'tinted': 'AppIcon-1024-tinted.png',
      });
      final ios = File('$set/AppIcon-1024.png').readAsBytesSync();
      expect(ios[25], 2, reason: 'the iOS icon must have no alpha channel');
      final d = await _rgba('$set/AppIcon-1024.png', size: 1024);
      expect(_px(d, 1024, 0, 0), _rgb(AppColors.primary),
          reason: 'full-bleed cloth to the corner');
      expect(_px(d, 1024, 563, 410), _rgb(AppColors.primaryForeground),
          reason: 'the quill in --paper-50');
      expect('#${_px(d, 1024, 7, 100).toRadixString(16).padLeft(6, '0').toUpperCase()}',
          weave.toUpperCase(),
          reason: 'the master carries the weave');

      // Tinted: PNG colour type 4 is gray + alpha. iOS asks for a grayscale
      // image, and the handoff's quill stands on nothing.
      final tinted = File('$set/AppIcon-1024-tinted.png').readAsBytesSync();
      expect(tinted[25], 4, reason: 'the tinted icon is gray + alpha');
      final t = await _rgba('$set/AppIcon-1024-tinted.png', size: 1024);
      expect(t.getUint8(3), 0, reason: 'clear to the corner');
      expect(t.getUint32((410 * 1024 + 563) * 4), 0xFFFFFFFF, reason: 'a white quill');

      // The layered icon: the cloth is the master without the quill, opaque;
      // the quill stands on nothing.
      const layers = 'ios/Runner/AppIcon.icon/Assets';
      expect(File('$layers/cloth.png').readAsBytesSync()[25], 2);
      final cloth = await _rgba('$layers/cloth.png', size: 1024);
      expect(_px(cloth, 1024, 0, 0), _rgb(AppColors.primary));
      expect(_px(cloth, 1024, 563, 410), _rgb(AppColors.primary),
          reason: 'no quill in the cloth');
      expect('#${_px(cloth, 1024, 7, 100).toRadixString(16).padLeft(6, '0').toUpperCase()}',
          weave.toUpperCase());
      final quill = await _rgba('$layers/quill.png', size: 1024);
      expect(quill.getUint8(3), 0, reason: 'clear to the corner');
      expect(_px(quill, 1024, 563, 410), _rgb(AppColors.primaryForeground));
      final mono = await _rgba('$layers/quill-mono.png', size: 1024);
      expect(mono.getUint8(3), 0, reason: 'clear to the corner');
      expect(mono.getUint32((410 * 1024 + 563) * 4), 0xFFFFFFFF, reason: 'a white quill');

      // Android legacy launchers: the flat drawing, on a rounded tile, because
      // a launcher below API 26 applies no mask.
      const sizes = {
        'mdpi': 48, 'hdpi': 72, 'xhdpi': 96, 'xxhdpi': 144, 'xxxhdpi': 192,
      };
      for (final e in sizes.entries) {
        final p = 'android/app/src/main/res/mipmap-${e.key}/ic_launcher.png';
        final a = await _rgba(p, size: e.value);
        final s = e.value;
        expect(_px(a, s, s * 563 ~/ 1024, s * 410 ~/ 1024), _rgb(AppColors.primaryForeground),
            reason: '$p: the quill');
        expect(_px(a, s, s ~/ 2, 2), _rgb(AppColors.primary),
            reason: '$p: the cloth at the top edge');
        expect(a.getUint8(3), lessThan(128), reason: '$p: a rounded corner is clear');
      }
    });
  });

  test('the app is called NoteLetter on the home screen and in the share sheet',
      () {
    // The Swift app that held the name is retired (ADR-175), so the suffix
    // that told the two apart has nothing left to distinguish.
    String displayName(String plist) {
      final m = RegExp(r'<key>CFBundleDisplayName</key>\s*<string>([^<]*)</string>')
          .firstMatch(File(plist).readAsStringSync());
      return m?.group(1) ?? '';
    }

    expect(displayName('ios/Runner/Info.plist'), 'NoteLetter');
    expect(displayName('ios/Share/Info.plist'), 'NoteLetter');
    final manifest =
        File('android/app/src/main/AndroidManifest.xml').readAsStringSync();
    expect(RegExp(r'<application[^>]*android:label="NoteLetter"').hasMatch(manifest),
        isTrue);
  });
}
